  create policy "Acesso total para Diretores e RH"
  on "public"."evaluations"
  as permissive
  for select
  to authenticated
using (((director_id = auth.uid()) OR (EXISTS ( SELECT 1
   FROM public.profiles
  WHERE ((profiles.id = auth.uid()) AND ((profiles.user_role = 'Diretor'::text) OR (profiles.assessoria = 'Recursos Humanos'::text)))))));



  create policy "Usuários podem criar avaliações"
  on "public"."evaluations"
  as permissive
  for insert
  to authenticated
with check ((auth.uid() = director_id));



  create policy "Usuários veem suas próprias avaliações"
  on "public"."evaluations"
  as permissive
  for select
  to authenticated
using ((auth.uid() = director_id));



  create policy "Leitura pública de perfis"
  on "public"."profiles"
  as permissive
  for select
  to authenticated
using (true);



  create policy "Usuários podem editar seu próprio perfil"
  on "public"."profiles"
  as permissive
  for update
  to authenticated
using ((auth.uid() = id));


CREATE TRIGGER on_auth_user_created AFTER INSERT ON auth.users FOR EACH ROW EXECUTE FUNCTION public.handle_new_user();


